"use client"; import {useEffect,useMemo,useState} from "react"; export function useCountdown(deadline:string){const [now,setNow]=useState(()=>Date.now());useEffect(()=>{const id=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(id)},[]);return useMemo(()=>{const remaining=Math.max(0,new Date(deadline).getTime()-now);return{remainingMs:remaining,days:Math.floor(remaining/86400000),hours:Math.floor(remaining/3600000)%24,minutes:Math.floor(remaining/60000)%60,seconds:Math.floor(remaining/1000)%60,expired:remaining===0}},[deadline,now])}
